import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"6.4 长期运行与 v1.0 验收","description":"长期稳定运行，完成整体验收后发布 v1.0。","frontmatter":{"title":"6.4 长期运行与 v1.0 验收","description":"长期稳定运行，完成整体验收后发布 v1.0。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/6-4.md","filePath":"delivery/stage-6/6-4.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-6/6-4.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_6-4-长期运行与-v1-0-验收" tabindex="-1">6.4 长期运行与 v1.0 验收 <a class="header-anchor" href="#_6-4-长期运行与-v1-0-验收" aria-label="Permalink to &quot;6.4 长期运行与 v1.0 验收&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 可以长期安静运行，并在完成全部能力验收后发布 v1.0。长期运行不只是“不崩溃”，还要资源可控、状态不漂移、权限不扩大。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>增加健康检查、资源上限、日志和异常提醒，出现问题时用户能知道。</li><li>定期清理临时文件、过期任务和不再需要的缓存，避免长期占用资源。</li><li>做至少数周的连续运行测试，检查内存、任务状态、同步和权限是否稳定。</li><li>完成覆盖主要任务类型的整体验收，包括安装、升级、备份、恢复、撤销和隐私说明。</li><li>检查所有高风险动作仍然需要审批，所有外部操作都有回执。</li><li>只有当用户可以独立安装、长期使用、迁移和退出时，才发布 v1.0。</li></ol>',5)])])}const v=a(r,[["render",o]]);export{p as __pageData,v as default};
